<?php if($access->can('maintenance.cost.view')): ?><section class="panel"><h2>Biaya Maintenance</h2><?php if($access->can('maintenance.cost.manage')): ?><form method="post" class="inline-form"><?= $this->csrf() ?><input type="hidden" name="action" value="cost_sync"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button type="submit">Sinkronkan biaya</button></form><?php endif ?><?php if(!$costs): ?><p>Belum ada biaya yang tervaluasi untuk Work Order ini.</p><?php else: ?><div class="table-scroll"><table><thead><tr><th>Kategori</th><th>Sumber</th><th>Deskripsi</th><th>Status Nilai</th><th>Total</th></tr></thead><tbody><?php foreach($costs as $c): ?><tr><td><?= $e($c['category']) ?></td><td><?= $e($c['source_ref']?:$c['source_type']) ?></td><td><?= $e($c['description']) ?></td><td><?= $e($c['valuation_status']) ?></td><td><?= $c['valuation_status']==='VALUED'?\Hls\Http\View::money($c['total_cost']): 'UNVALUED' ?></td></tr><?php endforeach ?></tbody></table></div><p><strong>Total tervaluasi: <?= \Hls\Http\View::money($costTotal) ?></strong><?php if($costIncomplete): ?> <span class="field-hint">Total belum lengkap karena terdapat komponen UNVALUED.</span><?php endif ?></p><?php endif ?></section><?php endif ?>

